insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 1, 'What does a survey station actually measure?', '["Measured depth, true vertical depth and the horizontal displacement from the wellhead, at that station.", "Measured depth, inclination and azimuth, and nothing else.", "Inclination, azimuth and dogleg severity, from which the position is then accumulated downwards.", "The three-dimensional position of the tool, resolved by the tool into north, east and vertical."]'::jsonb, 1, 'True vertical depth, north, east, dogleg, vertical section and closure are all computed from the three by a method somebody chose.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 2, 'Where does inclination come from?', '["A pendulum whose deflection is read optically and recorded against depth on the wireline.", "The magnetometers, resolved against the known dip angle of the earth''s field at that location.", "A gyroscope, which measures the rotation of the tool relative to an initialised reference.", "Three accelerometers measuring the direction of gravity in the tool''s own frame."]'::jsonb, 3, 'A gyro is an alternative for AZIMUTH, not for inclination. Gravity is large, constant and well known, which is why accelerometer inclination is the best-determined of the three measurements.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 3, 'Why are surveys taken at roughly thirty metre intervals?', '["Because a stand of pipe is about that long and the string must be stationary to take one.", "Because the error model is calibrated at that interval and using a different one invalidates it.", "Because thirty metres is the distance over which a bottom hole assembly can change direction appreciably.", "Because regulations require a station every thirty metres."]'::jsonb, 0, 'The interval is set by the rig''s pipe handling rather than by anything about the reservoir, and between two stations nothing is measured at all.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 4, 'A depth is quoted without saying what it is measured from. What is wrong?', '["Nothing: depth references in a field are standardised.", "The reference only matters for true vertical depth, and measured depth is unambiguous.", "It is not a depth: rig floor and mean sea level differ by tens of metres offshore.", "It matters only when comparing two wells, and within one well the reference cancels."]'::jsonb, 2, 'The reference cancels within one well only for differences. Any absolute depth, and any comparison against a map or another well, needs it.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 5, 'What is the well PATH, as distinct from the wellbore?', '["The centreline of the drilled hole, measured continuously by the tool as it is tripped out.", "A curve through the survey stations, with no diameter, doing whatever the method says between them.", "The planned trajectory, as opposed to the actual hole, which is the wellbore.", "The hole below the last casing shoe, which is the part still open to the formation."]'::jsonb, 1, 'Every number in this course is about the curve. The hole is what was drilled and nobody knows exactly where it is.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 6, 'At a connection, the sensor is 15 m behind the bit. What is known by measurement?', '["The position at the last survey station, which is behind the bit by at least the sensor offset.", "The position at the bit, since the tool projects the last attitude forward automatically.", "The position everywhere in the last stand, because the tool has been recording continuously.", "Nothing, until the string is tripped and a definitive survey is run."]'::jsonb, 0, 'The deepest surveyed point is never the bottom of the hole, and the projection ahead is where the well is being steered from.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 7, 'What is a definitive survey?', '["The survey taken at the deepest point of the well, which supersedes all shallower ones.", "The plan, once the well has been drilled and the plan has been accepted as achieved.", "The agreed record of where the well went, which may be a later gyro run.", "The average of all surveys taken in the hole, weighted by their stated accuracies."]'::jsonb, 2, 'Anti-collision uses the neighbour''s definitive survey if there is one and its PLAN if there is not, and those are very different things.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 8, 'A rate is recorded as 450 stb/d and the true rate was 500. What is the equivalent error in a survey?', '["An inclination error of the same proportion, since both enter the position linearly.", "An azimuth error, because both of the quantities are integrated along the hole to give a displacement.", "A dogleg severity error, since severity is a rate of change with respect to depth.", "There is no equivalent: rate is not a survey input, and the survey''s analogous input is the depth count."]'::jsonb, 3, 'The question is a trap from a different course. Survey inputs are depth, inclination and azimuth, and the depth count is the one that is counted rather than sensed.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 9, 'Why is the position reference the commonest reason an anti-collision scan is wrong?', '["Each well is stored relative to its own wellhead, and combining them needs the offsets.", "Because the reference is recorded only in the well header, which is often not transferred with the survey.", "Because different operators use different position references and the conversion is proprietary.", "Because the reference changes at a sidetrack and is rarely propagated."]'::jsonb, 0, 'Two wells cannot be compared unless they are in one frame. Forgetting the offsets puts both at the same place; applying them twice makes the wells look further apart, which nobody notices.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 10, 'What does the MWD tool give you?', '["The well path, computed downhole and transmitted to surface as positions.", "Inclination and azimuth at a depth the driller counted.", "A continuous record of the hole''s trajectory, sampled at whatever interval is requested.", "The position of the bit, corrected for the sensor offset by the tool''s own firmware."]'::jsonb, 1, 'The well path is what a piece of software makes of a list of those, and this course is about what the software is doing.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 11, 'Which of these is NOT computed from the three measured numbers?', '["Dogleg severity, which combines the inclination and azimuth change over an interval.", "Vertical section, projected onto a chosen azimuth.", "The total field strength at the well, which is an input from a geomagnetic model.", "Closure distance, which is the straight-line horizontal distance from the wellhead."]'::jsonb, 2, 'The field strength and the dip are inputs the error model needs, and it refuses to run without them.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 12, 'What is the practical consequence of the survey interval being set by pipe handling?', '["Surveys are taken at inconsistent intervals, so the error model has to interpolate them.", "The deepest station is always at a connection, so total depth is never surveyed.", "Dogleg severity is always reported over thirty metres regardless of the actual interval.", "The calculation has to assume a shape over ninety feet in which nothing was measured."]'::jsonb, 3, 'Every survey calculation method is a different assumption about exactly that gap, which is the subject of the next module.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 13, 'Two wells'' azimuths are referenced to different norths. What follows?', '["Nothing, provided both are internally consistent, since the difference cancels in a relative comparison.", "They are rotated relative to each other by the difference, which at kilometres of reach is tens of metres.", "Their inclinations are also affected, because the two quantities are derived from the same sensors.", "The error model corrects for it automatically, using the declination in each survey header."]'::jsonb, 1, 'The model converts azimuths using the header it is given. A header that misdescribes the data produces a correct calculation of the wrong well.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 14, 'Why does the station list matter more than the raw sensor readings?', '["Logs are shifted onto it, targets judged against it, neighbours cleared against it.", "Because the raw readings are proprietary to the survey contractor and are not delivered.", "Because the readings are corrected downhole and the raw values no longer exist at surface.", "Because the station list carries the uncertainty and the raw readings do not."]'::jsonb, 0, 'The station list IS the well as far as every downstream user is concerned, which is why an edited or deleted station moves answers quietly.'),
  ('welldesign', 'beginner', 'module', 'm01-what-a-survey-is', 15, 'What is the honest description of the well path as a model?', '["It is exact between stations, because minimum curvature is the true shape of a drilled hole.", "It is a rough approximation whose error nobody has ever quantified in a usable way.", "It is close enough for the questions this course asks, and its error is quantified next tier.", "It is exact at the stations and undefined between them, so no statement at all can be made in between."]'::jsonb, 2, 'The quantification is itself a published model with its own limits, and the Professional tier is about both.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 1, 'What does minimum curvature assume between two stations?', '["A straight line whose direction is the average of the two measured attitudes, weighted by interval length.", "A circular arc in the plane of both tangents, passing through both attitudes.", "A helix, since a bottom hole assembly rotates while it drills and traces a spiral.", "Nothing: it interpolates the positions rather than assuming a shape."]'::jsonb, 1, 'It is the shape of least total curvature consistent with both measurements, and it is close to what a stiff assembly actually drills.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 2, 'What does the dogleg formula combine?', '["The build rate and the turn rate, divided by the interval length to give a severity per unit depth.", "The measured depth interval and the position increment, giving the curvature of the arc.", "The inclination change and the azimuth change, into one total angle.", "The two attitudes and the interval, weighted by the sine of the average inclination."]'::jsonb, 2, 'A well that builds five degrees while turning thirty at high inclination has a much larger dogleg than either number alone.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 3, 'What is the ratio factor?', '["The correction that turns a balanced tangential increment into a circular arc.", "The ratio of measured depth to true vertical depth over the interval, used to scale the displacement.", "The ratio of the arc''s radius to the wellbore radius, which sets the bending stress in the pipe.", "The ratio of the dogleg to the build rate, which is one for a planar build and larger for a turn."]'::jsonb, 0, 'Its value is (2/beta) tan(beta/2), it is 1 for a straight interval, and everything else in the two methods is identical.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 4, 'At a five degree dogleg over one interval, how large is the ratio factor correction?', '["About six percent, which over 30 m is nearly two metres and is why the correction exists.", "About six parts in a hundred thousand, which is below the precision of any survey.", "It depends on inclination too, so no figure applies.", "About six parts in ten thousand, which over 30 m is under two centimetres."]'::jsonb, 3, 'It is small, it is free, it is always at least 1 so it accumulates one-signed, and it makes the calculation exact on a designed arc.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 5, 'What happens to the ratio factor formula at zero dogleg?', '["It returns 1 naturally, because the tangent of zero is zero and the limit is well behaved.", "It is zero divided by zero, so every implementation guards it and returns 1 below a threshold.", "It returns infinity, which propagates as an infinite position increment through the calculation.", "It is never evaluated, because a straight interval is handled by a separate code path."]'::jsonb, 1, 'A home-made survey spreadsheet without the guard produces a column of errors exactly where the well is straightest.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 6, 'What does the tangential method assume?', '["That the whole interval was drilled at the LOWER station''s attitude.", "That the interval was drilled at the average of the two stations'' attitudes, weighted equally.", "That the inclination varies linearly with measured depth across the interval while azimuth is fixed.", "That the hole is a circular arc, which is the same assumption minimum curvature makes."]'::jsonb, 0, 'On a build, the bottom of every interval is the steepest point in it, so the method treats every interval as steeper than it was.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 7, 'On the published example, how far out is the tangential method''s true vertical depth?', '["About two and a half feet shallow, which is within the precision the textbook prints.", "About twenty-five feet deep, because it over-counts the vertical component of each interval.", "About twenty-five feet shallow in two thousand feet of hole.", "It is exact, because the well is a planar constant build and the method has no azimuth error."]'::jsonb, 2, 'And about forty-three feet too far north. Three of the four classical methods agree within six tenths of a foot; the fourth does not.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 8, 'Why is the tangential method''s error systematic rather than random?', '["Because the survey interval is constant, so any per-interval error repeats identically.", "Because the method is applied by hand and human arithmetic errors are correlated.", "Because the error depends on the azimuth, which is nearly constant on a planar well.", "Because it uses the steepest attitude in every interval, so it errs the same way on every one."]'::jsonb, 3, 'A field mapped with tangential surveys is systematically shallow and its wells systematically too far out, which does not average away.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 9, 'Which classical method is closest to minimum curvature on the published example?', '["Balanced tangential, which is identical to minimum curvature apart from the ratio factor.", "Angle averaging, within two tenths of a foot of true vertical depth.", "The tangential method, since a constant build is the geometry it handles best.", "None: minimum curvature differs from all three by a foot."]'::jsonb, 1, 'Balanced tangential is within four tenths, which is very close and slightly further. Angle averaging''s weakness is azimuth wrap and strongly turning intervals.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 10, 'Why is minimum curvature exact on a compiled trajectory design?', '["Because the design is arcs and holds, and minimum curvature is the arc solution.", "Because the compiler subdivides finely enough that the residual error is below machine precision.", "Because the design is expressed in dogleg severity, its own input.", "It is not exact; it is merely the most accurate of the available methods on any station list."]'::jsonb, 0, 'That is why the course''s build-and-hold case reproduces its published endpoint to about four parts in ten billion.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 11, 'What does a longer survey interval cost?', '["Accuracy in inclination and azimuth, since the sensors drift between readings.", "Nothing measurable: the method is exact on any interval.", "Real dogleg is averaged away, and the assumed arc has more ground to cover.", "The position at the stations themselves, which becomes an interpolation rather than a measurement."]'::jsonb, 2, 'A sharp dogleg in the middle of a long interval is reported as a gentle average, and it is a real one that nobody accounts for.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 12, 'What does interpolating a survey to a one metre listing achieve?', '["A more accurate well path, because the assumed shape has less ground to cover between rows.", "More rows, all on the arc the original stations already implied, and no new information.", "A better dogleg severity, since the severity is then computed over a shorter reference length.", "Nothing at all, because the interpolation cannot be done without additional survey data."]'::jsonb, 1, 'It can be done, and its use is presentation and depth alignment. Only more MEASUREMENTS can detect that the assumption was wrong.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 13, 'Why is minimum curvature not exactly right on a drilled hole?', '["Because the ratio factor is a series approximation that is truncated after the first term.", "Because the method ignores the azimuth change, treating each interval as planar.", "Because survey sensors have errors, which the method does not account for.", "Because the hole is not a perfect arc: build rate varies, formation pushes, sliding alternates with rotating."]'::jsonb, 3, 'Sensor errors are real and are the next tier''s subject. The method''s own error is a property of the hole and shrinks as the interval shrinks.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 14, 'Where is the ratio factor''s effect largest?', '["In the tightest doglegs, where the arc bulges furthest from its chord.", "In the longest intervals, since the correction is proportional to the measured depth increment.", "At high inclination, where the vertical part is smallest.", "In the vertical section, where the dogleg is smallest and the guard threshold applies."]'::jsonb, 0, 'It grows with the dogleg angle alone. At 60 degrees over one interval, which is extreme, it is about ten percent.'),
  ('welldesign', 'beginner', 'module', 'm02-minimum-curvature', 15, 'What is the practical defence against a unit error in the survey constants?', '["Dimensional analysis of the formula, which catches any inconsistent unit combination.", "Recomputing in the other depth unit and confirming the two answers agree exactly.", "A sanity check on the answer, because the constants cannot be derived at the desk.", "Checking the ratio factor, which is dimensionless and therefore unaffected by unit errors."]'::jsonb, 2, 'Recomputing in the other unit is a good check and it will not catch a constant that is wrong in both. A plausible slope for the rate and rock is the defence.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 1, 'What are the two conventions for dogleg severity?', '["Total angle and planar angle, one including azimuth change and one ignoring it.", "Degrees per 100 ft and degrees per 100 m, which differ by a factor of about three point three.", "Degrees per 100 ft and degrees per 30 m, which are not the same number for one well.", "Degrees per station and degrees per unit length, the first depending on the survey interval used."]'::jsonb, 2, 'One hundred feet is 30.48 m, so the two figures differ by about one and a half percent. A limit quoted in the wrong one is quietly wrong.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 2, 'What is the build rate?', '["The inclination change per unit of measured depth, ignoring any azimuth change.", "The dogleg severity, which on a planar build is identical.", "The rate at which the assembly builds angle when sliding, excluding rotated intervals.", "The inclination change per unit of true vertical depth, which is what the design specifies."]'::jsonb, 0, 'It answers a different question from dogleg severity. A well turning hard at constant inclination has zero build rate and a large dogleg.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 3, 'Why can dogleg severity exceed both the build rate and the turn rate?', '["Because it is computed over the arc rather than the chord, which is always longer.", "Because it includes the ratio factor, which is always at least one.", "It cannot: dogleg severity is bounded above by the larger of the two.", "Because it combines them, and the azimuth part is scaled by the sine of inclination."]'::jsonb, 3, 'At 80 degrees inclination almost the whole turn rate counts. Near vertical, almost none of it does, which is why vertical wells turn cheaply.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 4, 'What is vertical section?', '["The total horizontal distance from the surface location, regardless of direction.", "Horizontal displacement projected onto one chosen azimuth, for plotting on a flat page.", "The vertical distance from surface to the current station, measured along the plumb line.", "The length of the well''s vertical hole above the kick-off point, before any build begins."]'::jsonb, 1, 'It needs a reference azimuth. Change the azimuth you project onto and every vertical section number in the listing changes.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 5, 'What is closure?', '["The straight-line horizontal distance from the surface reference to the station.", "The angle between the vertical section azimuth and the well''s actual bearing at the station.", "The horizontal distance remaining to the target from the current position, along the plan.", "The gap between planned and actual position."]'::jsonb, 0, 'Its direction is the closure azimuth. Together they say where the bottom of the hole sits, in polar rather than rectangular form.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 6, 'When does vertical section equal closure?', '["When the well is planar and stays in one plane.", "When the well is vertical, so that both quantities are zero and trivially equal.", "When the closure azimuth equals the reference azimuth you project onto.", "Never exactly: vertical section is a projection and is always the smaller of the two."]'::jsonb, 2, 'Otherwise vertical section is closure times the cosine of the angle between them, so it is smaller. On a planar well drilled on plan they coincide.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 7, 'A well is drilled 30 degrees off its planned vertical section azimuth. What does the plot show?', '["A vertical section equal to the closure distance.", "A vertical section about thirteen percent short of the true closure distance.", "A vertical section about thirty percent short, in proportion to the angular error.", "No change at all, because vertical section is computed from measured depth alone."]'::jsonb, 1, 'The cosine of 30 degrees is about 0.866. The well looks less far along than it is, and the error grows as the discrepancy grows.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 8, 'What does a survey listing show at every row?', '["Only the three measured quantities. The rest sits on a plot.", "The sensor readings themselves, before any correction for declination or grid convergence.", "The planned position and the actual position side by side, so the difference is visible.", "Measured depth, inclination, azimuth, and the positions and rates derived from them."]'::jsonb, 3, 'The three measured columns are data. The rest is arithmetic, so if the method or the reference changes, every derived column changes with it.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 9, 'Which column in a survey listing is a measurement rather than a calculation?', '["Inclination.", "True vertical depth, which the depth sensor reads directly at each station.", "Vertical section, which is read from the plot the directional driller maintains.", "Dogleg severity, which the steering tool reports at each survey point."]'::jsonb, 0, 'Measured depth, inclination, and azimuth are measured. Every other column is derived from them by a method the listing rarely names.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 10, 'Why does a dogleg severity limit belong to the equipment rather than the geometry?', '["Because geometry places no limit, so equipment must.", "Because a steerable assembly cannot exceed a given severity, so it is a capability limit.", "Because the limit protects casing, tubing, and wireline from bending stress.", "Because the limit is written into the drilling contract rather than the well plan."]'::jsonb, 2, 'The assembly''s capability is a separate constraint. A hole that can be drilled may still be one that a completion cannot be run into.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 11, 'What does a turn rate of zero with a nonzero dogleg mean?', '["The well is turning at constant inclination, which is the only way to have a dogleg without a build.", "The well is building or dropping angle in a fixed compass direction.", "The survey interval is too long, so the turn has been averaged out of the listing.", "The azimuth column is being reported to too few decimals to show the change."]'::jsonb, 1, 'That is the ordinary case in a two-dimensional well plan. The dogleg is then equal to the build rate.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 12, 'Why should a course-length dogleg severity always name its length?', '["Because the severity depends on the survey interval, which varies through the well.", "Because a severity with no length is dimensionless.", "Because different service companies compute the underlying angle differently.", "Because the same well gives different numbers per 100 ft and per 30 m."]'::jsonb, 3, 'The underlying angle per interval is the same. Only the length it is normalised to differs, and that is enough to fail an equipment check.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 13, 'What happens to a listing if the reference azimuth is changed after drilling?', '["The vertical section column changes and nothing else does.", "The whole listing changes, since every position is expressed relative to that azimuth.", "Nothing changes: the reference azimuth affects only the plot, not the tabulated values.", "Closure and closure azimuth change, since they are measured from the reference direction."]'::jsonb, 0, 'Closure is a distance from a point and does not care about the projection direction. Vertical section is a projection and cares about nothing else.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 14, 'What is the practical use of the closure azimuth?', '["It sets the reference azimuth that the vertical section plot should be projected onto.", "It gives the direction the assembly is currently pointing, which is what steering needs.", "It says which compass direction the bottom of the hole has moved.", "It is the angle between true north and grid north at the surface location."]'::jsonb, 2, 'It is a summary of where the well has gone, not where it is heading. The current azimuth column answers the heading question.'),
  ('welldesign', 'beginner', 'module', 'm03-reading-the-survey-table', 15, 'Why is a survey listing not a picture of the hole?', '["Because the stations are too far apart to show any of the detail that matters.", "Because it gives the path the hole centre followed, not the hole''s shape or size.", "Because it uses measured depth along the path rather than depth below the rig floor.", "Because the derived columns depend on a method that the listing does not state."]'::jsonb, 1, 'Spiralling, ledges, and washouts are all invisible in it. Every station is a point, and the path between points is an assumption.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 1, 'What three pieces make up a build-and-hold profile?', '["A build and a hold, in that order.", "A vertical section to the kick-off, a constant-rate build, then a straight hold to target.", "A vertical section, a build to maximum angle, a hold, and a drop back toward vertical at the end.", "A kick-off, a tangent, and a landing arc that brings the hole to horizontal at the reservoir."]'::jsonb, 1, 'It is the simplest useful shape and the one whose geometry closes in a single line of algebra.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 2, 'Why does an S-profile drop back toward vertical?', '["To land the well vertically in the reservoir, usually because the completion or a later sidetrack needs it.", "To reduce torque and drag.", "To keep the maximum inclination below the limit at which cuttings begin to form a bed on the low side.", "Because the target is closer to the surface location than a build-and-hold could reach at any build rate."]'::jsonb, 0, 'It costs more hole and more dogleg than a build-and-hold to the same target, so there has to be a reason for it.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 3, 'What makes a landing arc different from an ordinary build?', '["It uses a higher build rate.", "It is drilled with a rotary steerable rather than a mud motor, because the tolerance is tighter than sliding allows.", "It is the only part of the well where the dogleg severity limit is allowed to be exceeded briefly.", "It has to arrive at a stated inclination AND a stated depth at the same point."]'::jsonb, 3, 'Two conditions, so a single free build rate will not generally satisfy both. That is why landing is where designs most often fail to close.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 4, 'What is toolface?', '["The angle of the bit face to the rock.", "The inclination and azimuth the assembly will hold if it is rotated rather than slid through the interval.", "The direction the steering assembly''s deflection points, measured around the hole axis.", "The compass bearing the well is currently heading, which is the azimuth column of the survey listing."]'::jsonb, 2, 'It is a clock position around the hole. Zero at highside builds angle, ninety turns right, one hundred and eighty drops.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 5, 'A driller wants to build angle without turning. What toolface?', '["Right hand, ninety degrees.", "Highside, which is zero degrees measured from the top of the hole.", "It depends on the current inclination, because the toolface convention changes as the hole approaches vertical.", "Any toolface will build angle as long as the assembly has positive tendency; only the turn rate changes."]'::jsonb, 1, 'The convention is measured around the hole from highside. Near vertical there is no highside, so magnetic toolface is used instead.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 6, 'Why does a trajectory design have to be checked for closure?', '["Because the shapes are constrained, and not every target is reachable with the rates you specified.", "Because surveys drift.", "Because the compiler works in measured depth and the target is stated in true vertical depth and displacement.", "Because a design that closes on paper may still exceed the dogleg severity limit somewhere along its length."]'::jsonb, 0, 'The dogleg check is a separate and also necessary check. Closure asks the prior question of whether the geometry has a solution at all.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 7, 'What happens if a build-and-hold target is too shallow for the build rate?', '["The design simply fails.", "The compiler quietly reduces the build rate until the design closes, which is why the output can differ from the input.", "The hold section takes a negative length, which the compiler interprets as a drop section instead of a hold.", "The build alone overshoots the displacement, so no hold length can fix it."]'::jsonb, 3, 'The remedy is a lower build rate or a deeper kick-off. Reporting the failure rather than silently repairing it is what the compiler owes you.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 8, 'Which profile reaches a given displacement with the least measured depth?', '["The S-profile, always.", "A continuous-build profile with no hold section, because it turns every foot of hole into displacement.", "Build-and-hold, for a target the build rate can reach.", "It depends on the dogleg severity limit rather than the profile shape, so no general answer exists."]'::jsonb, 2, 'Every extra shape costs hole. The S-profile buys a vertical landing with more measured depth, more dogleg, and more drag.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 9, 'Why is the kick-off depth a design decision rather than a given?', '["Because casing points move.", "Because it trades shallow hole against the build rate and the maximum angle the well will hold.", "Because the formation strength varies with depth, and a kick-off in soft rock will not hold its tangent direction.", "Because the rig''s top drive can only initiate a deviation once the string weight exceeds a threshold value."]'::jsonb, 1, 'Kick off shallow and you can reach far with a gentle build. Kick off deep and you need a harder build or a steeper hold.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 10, 'What is a horizontal well''s landing point?', '["Where the well reaches its target inclination at the target depth, ready to drill the lateral.", "The bottom of the lateral.", "The point at which the well first crosses the top of the reservoir, whatever inclination it happens to have.", "The heel of the well, which is by convention the point where the completion''s first production port sits."]'::jsonb, 0, 'Heel and landing point are close but not identical: the heel is a completion term and the landing point is a geometric one.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 11, 'Why does a designed trajectory get compiled to a station list?', '["Because stations are shorter.", "Because the survey tool can only report at discrete depths, so the design must be sampled at those same depths.", "Because measured depth is the only depth reference that the driller can control, and stations are indexed by it.", "Because every downstream calculation reads stations, not shapes."]'::jsonb, 3, 'Clearance, torque and drag, casing wear, and hydraulics all take a station list. The design is the intent; the station list is the interface.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 12, 'What does the dogleg severity of a designed build section equal?', '["Zero, since the design is smooth.", "The build rate multiplied by the ratio factor, which accounts for the arc rather than the chord over each interval.", "The build rate, when the section builds at constant rate with no azimuth change.", "The build rate divided by the sine of the average inclination, which is how the azimuth term is normalised."]'::jsonb, 2, 'That equality is the reason a two-dimensional design''s dogleg check is simply a comparison of the build rate to the limit.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 13, 'Why check the dogleg of the compiled list rather than of the design?', '["Because the design has no dogleg.", "Because the joins between sections can carry a dogleg neither section had.", "Because the compiler applies a smoothing filter that can reduce the design''s stated rates below the drilled values.", "Because dogleg severity is only defined between two survey stations, so it cannot be evaluated on a continuous curve."]'::jsonb, 1, 'A hold that meets a build at a slight angular mismatch produces one bad interval that no section''s stated rate shows.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 14, 'What does a trajectory design not tell you?', '["Whether the hole can actually be drilled and completed, which torque, drag, and hydraulics answer.", "The measured depth at target.", "The true vertical depth at any point, which requires a survey listing rather than the design parameters.", "The dogleg severity along its length, which only becomes visible once real survey stations have been taken."]'::jsonb, 0, 'The geometry is necessary and it is not sufficient. A closable design can still be undrillable, and later courses are where that is settled.'),
  ('welldesign', 'beginner', 'module', 'm04-designing-a-trajectory', 15, 'At what inclination does an azimuth change contribute most to dogleg?', '["Near vertical, at low angle.", "At forty-five degrees, where the vertical and horizontal components of the displacement are equal in magnitude.", "Near horizontal, where the sine of inclination approaches one.", "It contributes equally at all inclinations, because azimuth and inclination enter the dogleg formula symmetrically."]'::jsonb, 2, 'Turning a horizontal well is expensive in dogleg. Turning a near-vertical one is nearly free, which is why azimuth is set early.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 1, 'What does a trajectory compiler take in and give out?', '["Design parameters in, and a station list of depth, inclination, and azimuth out.", "Surveys in, a design out.", "A target and a surface location in, and the single cheapest trajectory that connects them out.", "A station list in, and the corrected station list out after declination and convergence are applied."]'::jsonb, 0, 'It turns intent into the interface every other calculation reads. Nothing downstream knows what shape you asked for.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 2, 'Why does the compiled station interval matter?', '["It does not matter at all.", "Because the position at the final station depends on the interval, so a coarse list lands in a different place.", "Because a coarse list can hide a dogleg that a fine one shows.", "Because the compiler places stations only at section boundaries, so the interval sets how many sections there are."]'::jsonb, 2, 'Minimum curvature is exact on a designed arc, so the endpoint does not move. What moves is your ability to see the joins.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 3, 'What is crossing a TVD?', '["Reading the TVD column.", "Finding the measured depth at which the trajectory passes a stated true vertical depth.", "The point where the well crosses from above to below the true vertical depth of the shallowest offset well in the field.", "The depth at which true vertical depth stops increasing, which on an S-profile is the end of the drop section."]'::jsonb, 1, 'Casing points, formation tops, and pressure tests are all quoted in TVD, and the driller works in measured depth.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 4, 'Why can a TVD have more than one measured depth?', '["Because surveys repeat depths.", "Because true vertical depth is computed from inclination, which is ambiguous above ninety degrees in the listing.", "Because the compiler interpolates, and interpolation between two stations can produce more than one root.", "Because a well that drops below horizontal comes back up through the same TVD."]'::jsonb, 3, 'It is rare and it is real, in horizontal wells that undulate. Software that returns the first crossing and stops can mislead.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 5, 'What should a compiler refuse to do?', '["Silently change a parameter you gave it so that an impossible design appears to close.", "Compile an S-profile.", "Produce a station list at an interval finer than the survey interval the well will actually be surveyed at.", "Report a dogleg severity for a section whose build rate was specified directly in the design parameters."]'::jsonb, 0, 'A repaired design that is not flagged is worse than a failure, because the number you later rely on is not the number you asked for.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 6, 'What does a feasibility report tell you that a station list does not?', '["The measured depth at target.", "The dogleg severity of every interval, which the station list gives only as position rather than as curvature.", "Which constraint failed and by how much, when the design does not close.", "The uncertainty of each station, which depends on the survey tool and is not part of the geometric design."]'::jsonb, 2, 'A design either closes or it does not. When it does not, the useful output is a diagnosis rather than an empty list.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 7, 'What is the first thing to check in a compiled list?', '["That the file opens cleanly.", "That the last station lands on the target, in TVD and in horizontal displacement.", "That the dogleg severity is below the equipment limit at every interval along the whole compiled length.", "That the station interval is fine enough to resolve the joins between the design''s sections."]'::jsonb, 1, 'The dogleg and interval checks matter too, and they are worth nothing if the list does not go where you asked.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 8, 'Why compare the compiled endpoint against a published worked example?', '["Because publication is required.", "Because a published example uses the same units, so it detects any unit error the compiler may have introduced.", "Because the endpoint is the only quantity in the list that has a closed-form expression to compare against.", "Because it proves the compiler and your reading of it agree with a known answer."]'::jsonb, 3, 'This course''s build-and-hold case reproduces its reference endpoint to about four parts in ten billion, which leaves no room for a quiet error.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 9, 'What does a dogleg spike at one interval in an otherwise smooth list mean?', '["Two sections have been joined at an angular mismatch, or the section lengths do not add up.", "The survey tool malfunctioned.", "The station interval is too fine at that point, so numerical noise in the interpolation has been amplified.", "The design specified that dogleg deliberately, since a short high-severity interval is cheaper than a long gentle one."]'::jsonb, 0, 'It is a design defect, not a measurement one. There are no measurements in a compiled list.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 10, 'Why is the compiled list, not the design, what gets handed downstream?', '["Because it is a smaller file.", "Because the design parameters are commercially sensitive and the station list reveals less about the operator''s intent.", "Because clearance, torque and drag, and hydraulics all read stations.", "Because a station list can be updated with real surveys as the well is drilled, while a design cannot be updated at all."]'::jsonb, 2, 'It is the common interface. Every application in this module and the next reads the same three columns.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 11, 'What does the compiler do at a section boundary?', '["It smooths the transition.", "It ends one section''s geometry and starts the next, and any mismatch shows as a dogleg.", "It inserts a short blending arc whose curvature is the average of the two adjoining sections'' curvatures.", "It refuses to continue unless the two sections'' attitudes match to within the tolerance the design specified."]'::jsonb, 1, 'Whether it smooths or not is a choice the compiler makes, and you should know which one yours makes before you trust the dogleg column.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 12, 'A design closes but its build section exceeds the dogleg limit. What now?', '["Accept it and drill.", "Keep the build rate and shorten the build section, since the limit applies to total dogleg rather than to its rate.", "Increase the station interval so that the reported severity per interval falls below the equipment limit.", "Reduce the build rate and kick off shallower, then compile and check again."]'::jsonb, 3, 'Increasing the interval hides the dogleg without changing it, and the casing does not read the station list.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 13, 'What makes true vertical depth the depth that matters for pressure?', '["Because hydrostatic pressure depends on vertical height, not on the length of the path.", "Because it is measured directly.", "Because the mud column follows the hole, so its weight is proportional to the measured depth along that hole.", "Because formation tops are correlated between wells using measured depth, which makes TVD the comparison depth."]'::jsonb, 0, 'A horizontal well can add thousands of feet of measured depth at no change in pressure at all.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 14, 'What has to be true of a station list before it is used for clearance?', '["It must be finely sampled.", "It must be a compiled design rather than a measured survey, because measured surveys carry uncertainty.", "It must be in the same coordinate frame as every other well it is compared with.", "It must start at the same measured depth as the offset wells, so the two lists can be compared row by row."]'::jsonb, 2, 'Same north reference, same datum, same map projection. Two lists in different frames give a clearance number that means nothing.'),
  ('welldesign', 'beginner', 'module', 'm05-compiling-and-checking', 15, 'Why does a compiled design still need a real survey later?', '["Because the design expires.", "Because the hole goes where it goes, and only a survey says where that is.", "Because the compiler''s minimum curvature assumption is only approximate, and the survey uses an exact method instead.", "Because the station interval of the design is finer than the survey interval, so the two must be reconciled."]'::jsonb, 1, 'The design is a plan and the survey is a measurement. Confusing the two is how a plan becomes an unearned claim about the hole.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 1, 'After the Associate tier, what work can you honestly say you are able to do?', '["Design any well from scratch.", "Quantify how far the reported position could be from the true one, using an industry-standard error model.", "Read and reproduce a survey listing, and compile and check a simple design.", "Judge whether two wells are far enough apart to drill safely, using the separation factor and its thresholds."]'::jsonb, 2, 'The two other claims belong to the tiers above. This one is the foundation both of them stand on.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Why is the capstone graded on numbers rather than on prose?', '["Because a survey calculation has one right answer and the tolerance says how close is close enough.", "Because prose is slow to mark.", "Because the industry standard requires numeric verification of any position calculation before it is reported.", "Because the numbers are drawn from published references and prose cannot be checked against a published reference."]'::jsonb, 0, 'The tolerances are not the same for every field, and a tight one is a claim that the quantity is well conditioned.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 3, 'What single assumption does everything in this tier rest on?', '["That the survey tool is accurate.", "That true vertical depth is measured directly rather than being derived from inclination and measured depth.", "That the azimuth reference has been corrected for declination and grid convergence before the listing is produced.", "That the hole between two stations is a circular arc."]'::jsonb, 3, 'The reference question is real and it is the next tier''s. Between stations, the arc is the assumption everything else inherits.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Where does the tangential method''s error come from?', '["From ignoring azimuth entirely.", "From using the lower station''s attitude for the whole interval, which is the steepest point on a build.", "From the ratio factor being omitted, which is the only difference between it and the balanced tangential method.", "From an accumulation of rounding, since the method was designed to be worked by hand with slide rule precision."]'::jsonb, 1, 'Balanced tangential fixes it by averaging the two stations. Minimum curvature then adds the ratio factor on top of that.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What does the ratio factor correct for?', '["The difference between a chord and the arc that connects the same two attitudes.", "The unit of measured depth.", "The change in azimuth across the interval, which the balanced tangential method leaves out of the calculation.", "The systematic bias of the survey tool, which is a function of the total curvature the tool has passed through."]'::jsonb, 0, 'It is one at zero dogleg, always at least one, and it needs a guard where the dogleg is small enough to divide by.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Why does dogleg severity need a course length quoted with it?', '["Because it varies along the well.", "Because the underlying angle depends on the survey interval, which is not constant through most wells.", "Because the same interval gives different figures per 100 ft and per 30 m.", "Because equipment limits are quoted per unit length, so the severity must be normalised before comparison."]'::jsonb, 2, 'One hundred feet is 30.48 m, so the two are about one and a half percent apart. Enough to pass a check that should have failed.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 7, 'What does vertical section need that closure does not?', '["A surface reference position.", "A reference azimuth to project onto.", "A choice of depth reference, since the projection is taken in a plane defined relative to the rotary table.", "The current inclination at the station, because the projection is taken along the direction the well is heading."]'::jsonb, 1, 'Both need a surface reference. Only vertical section needs a direction, and changing that direction changes the whole column.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Which of these does the capstone ask you to reproduce?', '["A field''s production history.", "A separation factor between two wells, computed at the point where they come closest together.", "The confidence ellipse of a station, given the survey tool''s error model and the well''s attitude.", "A published worked example''s true vertical depth, and the error a weaker method makes on it."]'::jsonb, 3, 'The other two are the graded work of the professional and expert tiers, over the same well and the same standard cases.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Why does the course grade the tangential method''s error rather than just its answer?', '["Because the error is the point: it says what the method costs, in feet, on a real well.", "Because the answer is published.", "Because the tangential result on its own cannot be checked without knowing the reference method used alongside it.", "Because the error is more precisely defined than the depth itself, which depends on the reference datum chosen."]'::jsonb, 0, 'A number for the error turns a warning into a measurement, and a measurement is what changes what people do.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What does compiling a design prove?', '["That the well can be drilled.", "That the target is reachable within the survey uncertainty of the tools that will actually be run in the hole.", "That the geometry closes, and what dogleg it implies along the way.", "That the trajectory will clear every offset well, since clearance is computed from the same station list."]'::jsonb, 2, 'Drillability and clearance are separate questions with separate courses. Closure is the one the geometry answers.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What is the safest habit when you meet an unfamiliar survey listing?', '["Recompute every column yourself.", "Ask which method, which north, and which depth reference produced it.", "Compare it against the offset well listings in the same field, since a systematic error will show as a shared offset.", "Check that the dogleg severity column is consistent with the build and turn rate columns at every station."]'::jsonb, 1, 'The three columns of data are unambiguous. Every other column depends on choices that the listing usually does not state.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What did this tier deliberately leave out?', '["The minimum curvature method.", "The design of build-and-hold and S-profile trajectories, which belong to a planning course rather than a survey one.", "The distinction between measured depth and true vertical depth, which is assumed knowledge at every tier.", "How wrong the reported position might be, and how close another well is."]'::jsonb, 3, 'Those are exactly the professional and expert tiers of this course, in that order.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Why does the same well give different positions to different people?', '["Because they used different methods, different north references, or different datums.", "Because surveys are random.", "Because the calculation is sensitive to the order in which the stations are processed through the interval loop.", "Because position depends on the inclination convention, and some listings measure inclination from horizontal."]'::jsonb, 0, 'None of that is measurement error. It is convention, and conventions have to be stated to be checked.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What is the practical value of knowing minimum curvature is exact on a design?', '["It removes the need for surveys.", "It means the station interval can be made arbitrarily coarse without changing any position in the listing.", "It means any endpoint mismatch is your input or the compiler, not the method.", "It means the dogleg severity reported by the compiler is exactly the dogleg the assembly will drill."]'::jsonb, 2, 'It narrows the search when a number is wrong, which is most of what a check is for.'),
  ('welldesign', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What should you carry from this tier into the next?', '["That minimum curvature is exact.", "That every derived column depends on assumptions, and the next tier quantifies one of them.", "That the tangential method should never be used, since its error is systematic rather than random in nature.", "That a survey listing is a measurement, so the numbers in it can be relied on without further qualification."]'::jsonb, 1, 'The next tier''s whole subject is that the three measured columns are themselves uncertain, and by how much.'),
  ('welldesign', 'beginner', 'final', null, 1, 'A geologist hands you a formation top at 8,420 ft and asks where to set casing. What do you need to know first?', '["Whether the top was picked on logs or on cuttings, since the two disagree by a joint or so.", "Whether 8,420 is measured depth or true vertical depth.", "The mud weight in use at that depth, because the casing point is set by the pressure the shoe must hold.", "The dogleg severity above that point, since casing cannot be run through a section above the equipment limit."]'::jsonb, 1, 'In a deviated well the two can differ by thousands of feet. Everything else follows from settling that.'),
  ('welldesign', 'beginner', 'final', null, 2, 'Two survey listings for the same well disagree by 40 ft in TVD at total depth. Where do you look first?', '["At which calculation method each listing used, before assuming anything is broken.", "At the survey tool serial numbers.", "At the raw sensor readings, since a difference this large means one of the two tools was miscalibrated downhole.", "At the surface reference elevations, since a datum difference offsets every row of the listing by a constant."]'::jsonb, 0, 'A datum difference is a real possibility and it produces a constant offset from the first row. A method difference grows with depth.'),
  ('welldesign', 'beginner', 'final', null, 3, 'A directional driller reports a dogleg severity of 3.0. The casing limit is 3.0 per 100 ft. Is the well within limit?', '["Yes, since equal figures meet the limit.", "No, because a reported severity is an average over the interval and the peak within it will be higher than the average.", "Yes, provided the severity was computed by minimum curvature rather than by one of the older classical methods.", "Not until you know whether the reported figure is per 100 ft or per 30 m."]'::jsonb, 3, 'Per 30 m, 3.0 is about 3.05 per 100 ft, which is over. The interval-averaging point is also real and it is a separate one.'),
  ('welldesign', 'beginner', 'final', null, 4, 'A well plan shows 6,000 ft measured depth and 5,800 ft TVD at the shoe. What does that tell you?', '["The plan has an error in it.", "The well kicked off at 5,800 ft and built angle over the last 200 ft of measured depth before reaching the shoe.", "The hole is deviated, and about 200 ft of path has bought no vertical depth.", "The survey interval is 200 ft, which is the difference the two depth columns show at the shoe."]'::jsonb, 2, 'It says nothing about where the deviation is. The difference is a total, and the same total fits many shapes.'),
  ('welldesign', 'beginner', 'final', null, 5, 'You are asked to plot a well''s progress against plan on a vertical section view. What do you have to fix first?', '["The vertical scale of the plot.", "The reference azimuth, since both curves must be projected onto the same one.", "The survey calculation method, since the plan is a compiled design and the actual is a measured survey listing.", "The datum, since the plan is usually referenced to mean sea level and the survey to the rotary table."]'::jsonb, 1, 'Datum matters for depth. The reference azimuth is the one that quietly makes two curves incomparable while both look right.'),
  ('welldesign', 'beginner', 'final', null, 6, 'A junior engineer computes TVD with the tangential method because the spreadsheet was already written. What do you tell them?', '["The error is systematic and shallow, so the whole well maps too high and it does not average out.", "It is fine for a vertical well.", "Use balanced tangential instead, which corrects the bias entirely and is simpler than minimum curvature to write.", "Rerun it at a finer survey interval, which reduces the error to below the precision anybody will read from it."]'::jsonb, 0, 'It is fine for a vertical well, and that is not the point in a deviated one. On a 2,000 ft build it was about 25 ft shallow.'),
  ('welldesign', 'beginner', 'final', null, 7, 'A well is at 85 degrees inclination and turns 10 degrees in azimuth over one interval. How does that show up?', '["As no dogleg at all, since inclination did not change.", "As about 5 degrees of dogleg, because the azimuth contribution is halved at inclinations above the horizontal.", "As 10 degrees of build rate, since the dogleg formula converts azimuth change into equivalent inclination change.", "As nearly the full 10 degrees of dogleg, because the sine of 85 degrees is close to one."]'::jsonb, 3, 'Near vertical the same turn would cost almost nothing. That asymmetry is why azimuth is set while the well is still shallow.'),
  ('welldesign', 'beginner', 'final', null, 8, 'A design closes on paper but the compiler reports a dogleg spike at one interval. What is the most likely cause?', '["The station interval is too coarse.", "The build rate specified for the section above the spike exceeds what a steerable assembly can physically deliver.", "Two sections joined at a slight angular mismatch, which no single section''s rate shows.", "The compiler applied the ratio factor at that interval, which inflates the reported severity above the design rate."]'::jsonb, 2, 'It is a defect in the design, not the compilation. Checking each section''s stated rate would never have found it.'),
  ('welldesign', 'beginner', 'final', null, 9, 'A colleague says minimum curvature is exact. When are they right?', '["On a compiled design made of arcs and straight holds, which is exactly the shape it assumes.", "Never, since real holes are not arcs.", "Whenever the survey interval is short enough that the assumed arc has little ground to cover between stations.", "Whenever the dogleg severity is below about five degrees per 100 ft, where the ratio factor correction is negligible."]'::jsonb, 0, 'On a drilled hole it is an assumption like any other. The distinction between a plan and a measurement runs through the whole course.'),
  ('welldesign', 'beginner', 'final', null, 10, 'The team wants to interpolate a survey to one metre stations for a casing wear study. What do you point out?', '["Interpolation is not possible.", "The extra rows carry no new information, only the arc the original stations already implied.", "The interpolation must use the same method as the original listing, or the interpolated positions will not match.", "Casing wear needs true vertical depth rather than measured depth, so a finer measured depth listing does not help."]'::jsonb, 1, 'It is useful for depth alignment and it is not a better survey. A sharp dogleg inside an original interval stays invisible.'),
  ('welldesign', 'beginner', 'final', null, 11, 'A vertical section plot shows the well 300 ft short of plan, but closure matches. What happened?', '["The survey tool under-read measured depth.", "The plan and the actual were compiled with different station intervals, which changes the projection but not the distance.", "The datum used for the actual listing is 300 ft below the one used for the plan, offsetting the projection.", "The well went the planned distance in a different direction from the reference azimuth."]'::jsonb, 3, 'Closure is a distance and does not care about direction. Vertical section is a projection and cares about nothing else.'),
  ('welldesign', 'beginner', 'final', null, 12, 'You are handed a station list with no header. What three columns must be present for it to be usable?', '["North, east, and TVD.", "Measured depth, true vertical depth, and dogleg severity, from which the attitude at each station can be recovered.", "Measured depth, inclination, and azimuth.", "Measured depth, vertical section, and closure, which together fix the horizontal position at every station."]'::jsonb, 2, 'North, east, and TVD are also a complete description of position, and they are already a calculation. The three measured columns are the data.'),
  ('welldesign', 'beginner', 'final', null, 13, 'An S-profile and a build-and-hold both reach the same target. Which costs more hole?', '["The S-profile, which adds a drop section and the measured depth to turn through it.", "The build-and-hold, always.", "It depends on the kick-off depth, since a deeper kick-off requires more build and therefore more measured depth.", "Neither: two designs to the same target have the same measured depth by the geometry of the closure condition."]'::jsonb, 0, 'It buys a vertical landing. Whether that is worth the extra hole, dogleg, and drag is the design decision.'),
  ('welldesign', 'beginner', 'final', null, 14, 'A completion engineer asks whether a 4 degree per 100 ft dogleg is acceptable. What is the honest answer?', '["Four degrees is always acceptable.", "It depends on what is being run through it and how stiff that equipment is.", "It depends on the inclination at that point, since bending stress scales with the vertical component of the dogleg.", "It depends on the survey interval, because a severity computed over a longer interval understates the peak curvature."]'::jsonb, 1, 'The interval point is real and separate. The limit itself belongs to the casing, the tubing, and the tools, not to the geometry.'),
  ('welldesign', 'beginner', 'final', null, 15, 'Why is a horizontal well''s measured depth so much larger than its TVD?', '["Because the survey interval is finer there.", "Because true vertical depth is measured from the rotary table while measured depth is measured from the seabed.", "Because the minimum curvature method under-reports vertical depth at inclinations approaching ninety degrees.", "Because a horizontal lateral adds path length at almost no vertical gain."]'::jsonb, 3, 'It also means that thousands of feet of hole add nothing to the hydrostatic column, which is a hydraulics consequence.'),
  ('welldesign', 'beginner', 'final', null, 16, 'The build rate column reads zero and the dogleg column reads 2.5. Is the listing wrong?', '["Yes, the two columns must agree.", "No, but only if the inclination is close to vertical, where the build rate is not defined and the column reads zero.", "No: the well is turning at constant inclination, and turning shows in dogleg only.", "Yes, unless the well is exactly horizontal, where the azimuth term is scaled to zero in the dogleg formula."]'::jsonb, 2, 'Build rate ignores azimuth. Dogleg combines both, and at high inclination almost the whole turn counts.'),
  ('welldesign', 'beginner', 'final', null, 17, 'You need the measured depth at which the well crosses 7,000 ft TVD. The listing has stations at 6,900 and 7,150 ft TVD. What do you do?', '["Interpolate along the arc between those two stations rather than linearly between the rows.", "Take the deeper station and note it.", "Use the average of the two measured depths, weighted by how far 7,000 sits between the two TVD values.", "Request a survey at that exact depth, since interpolation between stations is not defensible for a casing point."]'::jsonb, 0, 'Linear interpolation between rows is a common shortcut and it is wrong by the same amount the arc bulges from the chord.'),
  ('welldesign', 'beginner', 'final', null, 18, 'Two wells'' station lists were produced by different service companies. What must you confirm before comparing them?', '["That both used minimum curvature.", "That both use the same north reference, the same datum, and the same map projection.", "That both were surveyed with the same tool type, since different tools have different error characteristics.", "That both start at the same measured depth, so the rows can be compared against each other one for one."]'::jsonb, 1, 'The method matters too, and it is the smaller of the two effects. A frame mismatch makes the comparison meaningless rather than merely imprecise.'),
  ('welldesign', 'beginner', 'final', null, 19, 'What does a driller actually control while steering?', '["The inclination and azimuth directly.", "The dogleg severity, which is set on the surface console and held by the rotary steerable system automatically.", "The measured depth at which each survey station is taken, which sets the resolution of the resulting listing.", "Toolface and how much of the interval is slid rather than rotated."]'::jsonb, 3, 'Inclination and azimuth are the outcome. The lever is where the deflection points and how long it is allowed to act.'),
  ('welldesign', 'beginner', 'final', null, 20, 'A well plan specifies a kick-off at 2,000 ft. The team proposes moving it to 4,000 ft. What follows?', '["A higher build rate or a steeper hold angle will be needed to reach the same target.", "The measured depth at target falls.", "The dogleg severity falls, because the build has more measured depth available to achieve the same angle change.", "Nothing changes downhole, since the target displacement is fixed and the geometry adjusts the hold length only."]'::jsonb, 0, 'Kicking off deeper leaves less hole to turn the corner in. That is the whole trade the kick-off depth controls.'),
  ('welldesign', 'beginner', 'final', null, 21, 'A report quotes closure of 1,200 ft at an azimuth of 042. What does that mean?', '["The well is heading 042 at total depth.", "The well has drilled 1,200 ft of hole since kicking off, along a bearing that averaged 042 over that interval.", "The bottom of the hole is 1,200 ft horizontally from surface, in the direction 042.", "The target lies 1,200 ft away on a bearing of 042 from the current bottom hole position of the well."]'::jsonb, 2, 'It is a summary of where the well has gone, in polar form. The current azimuth column answers where it is heading.'),
  ('welldesign', 'beginner', 'final', null, 22, 'The capstone asks for a difference in feet, not a depth. What does that buy?', '["Because the depth alone is published.", "Because the error is the useful quantity: it puts a number in feet on what the method costs.", "Because the error is better conditioned than the depth, which depends on the datum and the reference elevation chosen.", "Because grading a difference removes any dependence on the units the two calculations were performed in."]'::jsonb, 1, 'A warning becomes a measurement, and a measurement is the thing that changes what people actually do.'),
  ('welldesign', 'beginner', 'final', null, 23, 'A spreadsheet returns a division error on the vertical section of a well. What is the likely cause?', '["The reference azimuth is undefined.", "The closure azimuth is zero at that station, which makes the projection cosine undefined in most implementations.", "The inclination reached exactly ninety degrees, which puts the vertical component of the increment at zero.", "An unguarded ratio factor at an interval where the dogleg is essentially zero."]'::jsonb, 3, 'The formula is zero over zero at zero dogleg. The errors appear exactly where the well is straightest, which is why they surprise people.'),
  ('welldesign', 'beginner', 'final', null, 24, 'What does a landing arc have to satisfy that an ordinary build does not?', '["Both a target inclination and a target depth, at the same point.", "A tighter dogleg severity limit.", "A constant build rate throughout, since a variable rate would prevent the completion from being run to the toe.", "A specified azimuth as well as inclination, because the lateral must be drilled along the reservoir''s preferred direction."]'::jsonb, 0, 'Two conditions and generally one free rate, so a single free build rate will not usually satisfy both.'),
  ('welldesign', 'beginner', 'final', null, 25, 'A survey listing shows TVD increasing, then decreasing, then increasing again. What is the well doing?', '["The listing is corrupt.", "Drilling an S-profile, in which the drop section brings the well back up before the final hold to target depth.", "Undulating around horizontal, so the same TVD occurs at more than one measured depth.", "Sidetracking, which restarts the depth reference and produces a discontinuity in the true vertical depth column."]'::jsonb, 2, 'It is real and it means software that returns the first TVD crossing and stops can quietly mislead you.'),
  ('welldesign', 'beginner', 'final', null, 26, 'Why does every derived column in a listing depend on choices the listing rarely states?', '["Because the columns are computed by hand.", "Because method, north reference, datum, and reference azimuth are all choices, not measurements.", "Because service companies use proprietary algorithms whose details are not disclosed to the operator on delivery.", "Because the derived columns are recomputed each time the listing is opened, using the current software''s defaults."]'::jsonb, 1, 'The three measured columns are unambiguous. Everything downstream of them inherits a set of decisions.'),
  ('welldesign', 'beginner', 'final', null, 27, 'What is the fastest check that a compiled design is worth reading further?', '["Does the file have the right number of rows.", "Is the dogleg severity below the limit at every interval, which is the constraint that most designs fail on.", "Is the station interval fine enough to reveal any mismatch at the joins between the design''s sections.", "Does the last station land on the target in TVD and in horizontal displacement."]'::jsonb, 3, 'The other checks matter and they are worthless on a design that does not go where you asked it to go.'),
  ('welldesign', 'beginner', 'final', null, 28, 'A team is told the well is 500 ft from a producer. What is missing from that statement?', '["Whether 500 ft is centre to centre, and how uncertain each of the two positions is.", "The direction of the offset well.", "The measured depth at which the two wells are 500 ft apart, since the distance changes along the well path.", "Whether the two positions were computed with the same survey calculation method and the same station interval."]'::jsonb, 0, 'The measured depth point is a real omission too. The uncertainty question is what the expert tier of this course exists to answer.'),
  ('welldesign', 'beginner', 'final', null, 29, 'The method is exact on a design. What breaks that when the hole is real?', '["Because the ratio factor is truncated.", "Because the survey sensors have errors, which propagate into every position the method computes from them.", "Because build rate varies, sliding alternates with rotating, and the rock pushes back.", "Because the method assumes constant azimuth over each interval, and real intervals turn as well as build."]'::jsonb, 2, 'Sensor error is real and it is a separate subject. The method''s own error is a property of the hole, and it shrinks as the interval shrinks.'),
  ('welldesign', 'beginner', 'final', null, 30, 'A design''s build section is at the dogleg limit exactly. What is the practical risk?', '["There is no risk at the limit.", "The drilled hole will vary around the design, so half the intervals will exceed the limit.", "The compiler may apply the ratio factor, which will push the reported severity above the limit in the output list.", "The limit applies to the completion rather than to drilling, so it can be exceeded during drilling without consequence."]'::jsonb, 1, 'A design at the limit has no margin for how the hole actually gets drilled, and it always gets drilled with scatter.'),
  ('welldesign', 'beginner', 'final', null, 31, 'Which of these does a station list not contain?', '["The position of the hole centre.", "The inclination and azimuth at each surveyed depth, which are the two attitude measurements the tool provides.", "The measured depth at each station, from which the intervals between stations are obtained by differencing.", "The shape and size of the hole, including washouts, ledges, and spiralling."]'::jsonb, 3, 'Every station is a point on the centreline. The list is a path, not a picture.'),
  ('welldesign', 'beginner', 'final', null, 32, 'The compiler reports that a build-and-hold design does not close. What is the first parameter to change?', '["The build rate, since a gentler build reaches further before the hold begins.", "The target depth.", "The station interval, since a finer interval lets the compiler resolve the closure condition more precisely.", "The reference azimuth, because the closure condition is evaluated in the vertical section plane the azimuth defines."]'::jsonb, 0, 'A shallower kick-off does the same job. The target is usually the one parameter you are not free to move.'),
  ('welldesign', 'beginner', 'final', null, 33, 'Why do casing points get quoted in TVD?', '["Because TVD is measured directly.", "Because casing is run in joints of fixed length, and the count of joints is determined by the vertical interval.", "Because the pressure the shoe must hold depends on vertical height, not path length.", "Because formation tops are correlated between wells in TVD, so a casing point set in TVD is transferable."]'::jsonb, 2, 'The correlation point is true and secondary. The pressure argument is why it must be TVD and cannot be measured depth.'),
  ('welldesign', 'beginner', 'final', null, 34, 'A survey is taken every 90 ft instead of every 30 ft. What is lost?', '["Nothing, since the method is exact.", "The ability to see real dogleg inside the interval, which is reported as a gentle average.", "The accuracy of the position at the stations themselves, which becomes an interpolation rather than a measurement.", "The dogleg severity column entirely, since severity is only defined over an interval of standard course length."]'::jsonb, 1, 'The stations are still measurements. What is lost is everything that happened between them.'),
  ('welldesign', 'beginner', 'final', null, 35, 'Why does a well plan state a maximum inclination as well as a build rate?', '["Because the survey tool has an inclination limit.", "Because the dogleg severity limit is expressed as a maximum inclination change over a standard course length.", "Because the completion cannot be run below a threshold inclination without a tractor or coiled tubing assistance.", "Because the hold angle sets how far the well reaches and what it costs in drag."]'::jsonb, 3, 'The completion point becomes a constraint in later courses. Here it is geometry: the hold angle and the build rate together fix the reach.'),
  ('welldesign', 'beginner', 'final', null, 36, 'What does it mean that the ratio factor is always at least one?', '["The correction always lengthens the increment, so its effect accumulates one-signed along the well.", "It means the correction can be ignored.", "It means minimum curvature always reports a deeper true vertical depth than the balanced tangential method does.", "It means the arc is always longer than the chord, which is the definition of the ratio the factor expresses."]'::jsonb, 0, 'One-signed accumulation is why a small per-interval correction is worth applying on a long well.'),
  ('welldesign', 'beginner', 'final', null, 37, 'A design is handed over as a station list rather than as design parameters. What is lost?', '["The position of every station.", "The dogleg severity, which is a design parameter and cannot be recovered from positions alone without the method.", "The intent: which rates were specified, and which were the compiler''s own choices.", "The target definition, since a station list ends at total depth rather than at the geological target it was aimed at."]'::jsonb, 2, 'Dogleg is recoverable from the list. What is not recoverable is what you asked for versus what you got.'),
  ('welldesign', 'beginner', 'final', null, 38, 'Why does the same target need a different build rate from a different surface location?', '["Because the north reference changes.", "Because the horizontal displacement changes, and the geometry has to cover it.", "Because the kick-off depth is fixed by the formation, so a longer reach must be achieved entirely by a harder build.", "Because the dogleg limit is a property of the rig, and different surface locations use different rigs."]'::jsonb, 1, 'The kick-off depth is also free, and moving it is the usual first response to a reach that a build rate cannot make.'),
  ('welldesign', 'beginner', 'final', null, 39, 'What single question would you ask about an unfamiliar dogleg severity limit?', '["Which service company set it.", "Whether it applies to the design or to the drilled hole, since the drilled hole always exceeds the design somewhere.", "Whether it was computed by minimum curvature or by one of the classical methods the industry used before it.", "What length it is normalised to, per 100 ft or per 30 m."]'::jsonb, 3, 'The design-versus-drilled distinction is also worth asking. The unit is the one that turns a pass into a fail with no other change.'),
  ('welldesign', 'beginner', 'final', null, 40, 'A survey listing has been recomputed with a new reference azimuth. Which columns changed?', '["Vertical section, and nothing else.", "Every position column in the listing.", "Closure and closure azimuth, which are both measured relative to the reference direction the listing declares.", "Vertical section and dogleg severity, since both are evaluated in the plane the reference azimuth defines."]'::jsonb, 0, 'Closure is a distance from a point. Dogleg is an angle between attitudes. Neither knows what direction you chose to plot on.'),
  ('welldesign', 'beginner', 'final', null, 41, 'What does the associate tier of this course leave for the tiers above it?', '["The minimum curvature calculation itself.", "The design of build-and-hold and S-profile trajectories, which are covered in a separate well planning course.", "How uncertain the reported position is, and how close another well is.", "The distinction between measured depth and true vertical depth, which requires the error model to be meaningful."]'::jsonb, 2, 'Those two questions are the professional and expert tiers exactly, in that order, over the same well and the same standards.'),
  ('welldesign', 'beginner', 'final', null, 42, 'You reproduce a published example''s TVD to four parts in ten billion. What has that proved?', '["That the well was drilled correctly.", "That your reading of the method and your inputs both match the reference.", "That minimum curvature is more accurate than the classical methods, which the same example also demonstrates.", "That the survey tool used on the published well was calibrated to the same standard your calculation assumes."]'::jsonb, 1, 'It is a check on you and on the software, not on the hole. That is exactly what makes it worth doing before anything else.');
