-- ============================================================================
-- DR1 ASSOCIATE DEEP SEED: Well Design & Surveys, beginner tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, so the seeded structure and the
-- shipped lesson files cannot disagree.
--
-- What this tier owns: the survey calculation itself. What the three measured
-- columns are and what every other column is derived from; the circular arc
-- minimum curvature assumes between two stations and the ratio factor that
-- makes it exact; the three classical methods it replaced, and the 25 ft that
-- the tangential method costs on a 2000 ft build; dogleg severity and its two
-- course-length conventions; vertical section, closure, and the reference
-- azimuth that only one of them needs; the four trajectory shapes and what
-- each buys; and the compiler that turns a design into the station list every
-- downstream calculation reads.
--
-- Every number in the lessons is derived by running the vendored
-- engines/drilling against its own goldens, and the teaching lab that the
-- panels and this course share is pinned to the same values by
-- welldesignLab.test.js. A numeric sweep over the lessons resolved all
-- literals carrying seven or more significant figures to an engine-derived
-- value; a tier-leakage sweep over the lessons and the banks reports zero
-- downward leaks and zero same-tier answer prints against all eighteen
-- graded fields.
--
-- Answer keys live only here and in academy_quiz_questions, which has no
-- client SELECT policy.
-- ============================================================================

values ('welldesign', 'beginner', '{"modules":[{"key":"m01-what-a-survey-is","title":"What a Survey Is","lesson_keys":["l01-three-numbers-at-a-depth","l02-the-wellbore-is-not-the-wellpath","l03-measured-depth-and-true-vertical-depth","l04-azimuth-and-which-north"]},{"key":"m02-minimum-curvature","title":"Minimum Curvature","lesson_keys":["l01-the-arc-between-two-stations","l02-the-ratio-factor","l03-the-methods-it-replaced","l04-what-the-tangential-method-costs","l05-why-the-survey-interval-matters"]},{"key":"m03-reading-the-survey-table","title":"Reading the Survey Table","lesson_keys":["l01-the-listing-a-driller-reads","l02-dogleg-severity-and-its-two-conventions","l03-build-rate-and-turn-rate","l04-vertical-section","l05-closure-and-when-it-equals-the-vertical-section"]},{"key":"m04-designing-a-trajectory","title":"Designing a Trajectory","lesson_keys":["l01-the-shapes-and-when-to-use-them","l02-build-and-hold","l03-the-s-profile","l04-landing-a-horizontal","l05-toolface-and-steering-to-a-target"]},{"key":"m05-compiling-and-checking","title":"Compiling and Checking","lesson_keys":["l01-from-a-design-to-a-station-list","l02-the-dogleg-the-design-implies","l03-crossing-a-tvd","l04-what-the-compiler-will-not-let-you-do"]},{"key":"m06-the-associate-reading","title":"The Associate Reading","lesson_keys":["l01-the-story-so-far","l02-working-the-capstone","l03-onward"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
      content_version = excluded.content_version,
      active = true,
      updated_at = now();

delete from public.academy_quiz_questions
 where app_slug = 'welldesign' and tier = 'beginner';

